// probe.test.js — sonde temporaire (supprimée avant livraison).
// Cas des familles non couvertes par game/sonde.test.js : paddle, angle mort,
// vitesse, dépendance à dt. Chaque cas est rouge sur le code d'aujourd'hui.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  step,
  createState,
  ballSpeed,
  BALL_R,
  PADDLE_Y,
  PADDLE_H,
  PADDLE_W,
  WIDTH,
} from '../game/neon.js';

const DT = 1 / 60;
const DT_MAX = 0.05;

// D7 — Paddle : traversée par le haut à grande vitesse.
// Niveau 7, 60 fps : 800 * 1/60 = 13.3 px > 12 px (hauteur du paddle) : le bord
// bas saute par-dessus la bande testée et la balle traverse. (Niveau 1 + frame
// à 50 ms : 13 px > 12 px — le défaut est accessible très tôt.)
test('D7 rouge: paddle hit at high speed must bounce at the top face', () => {
  const state = createState(7);
  state.paddle.x = (WIDTH - PADDLE_W) / 2;
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R, r: BALL_R, vx: 0, vy: ballSpeed(7) };

  const lost = step(state, DT);

  assert.equal(lost, false, 'fast ball must bounce off the paddle, not fall through');
  assert.ok(state.ball.vy < 0, `vy must flip up after the paddle bounce: ${state.ball.vy}`);
  assert.equal(
    state.ball.y + state.ball.r,
    PADDLE_Y,
    'after the bounce the ball rests exactly on the top face',
  );
});

// D7b — le miroir : une balle déjà sous le paddle l'a raté, elle ne doit pas
// être renvoyée vers le haut par une bande élargie.
test('D7 rouge: a ball below the paddle has missed it and must keep falling', () => {
  const state = createState(1);
  state.paddle.x = (WIDTH - PADDLE_W) / 2;
  state.ball = { x: WIDTH / 2, y: PADDLE_Y + PADDLE_H, r: BALL_R, vx: 0, vy: ballSpeed(1) };

  step(state, DT);

  assert.ok(state.ball.vy > 0, `a missed paddle must not bounce the ball up: ${state.ball.vy}`);
});

// D8 — Angle mort : un contact au centre exact du paddle donne vx = 0 et la
// balle boucle à la verticale, injouable.
test('D8 rouge: center paddle hit must not send the ball vertical', () => {
  const state = createState(1);
  state.paddle.x = (WIDTH - PADDLE_W) / 2;
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R, r: BALL_R, vx: 0, vy: ballSpeed(1) };

  step(state, DT);

  assert.ok(state.ball.vx !== 0, `vx must stay playable: ${state.ball.vx}`);
  assert.ok(
    Math.abs(state.ball.vx) >= ballSpeed(1) * 0.15,
    `vx must not be near zero: ${state.ball.vx}`,
  );
});

// D9 — Vitesse : le rebond paddle réécrit vx sans renormaliser, la norme monte
// jusqu'à 1.166 * speed sur le bord.
test('D9 rouge: paddle bounce conserves the level speed', () => {
  const state = createState(1);
  state.paddle.x = (WIDTH - PADDLE_W) / 2;
  const hit = 0.8;
  state.ball = {
    x: WIDTH / 2 + hit * (PADDLE_W / 2),
    y: PADDLE_Y - BALL_R,
    r: BALL_R,
    vx: 0,
    vy: ballSpeed(1),
  };

  step(state, DT);

  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(
    Math.abs(norm - ballSpeed(1)) < 0.5,
    `speed must be conserved: |v| = ${norm}, speed = ${ballSpeed(1)}`,
  );
});

// D10 — Dépendance à dt : la même trajectoire doit donner le même rebond à
// 60 fps et à la frame plafonnée. Aujourd'hui : à 1/60 la balle finit dans la
// brique (détection discrète), à 0.05 elle la franchit sans la voir.
test('D10 rouge: same trajectory, same collision at 60 fps and at the dt cap', () => {
  const mk = () => {
