// --- Playtest defects (see .scratch/to_fix.md, D7-D10) ----------------------

// D7 — the fast ball jumps over the discrete paddle band check and falls
// through. ballSpeed(7) = 800 px/s, dt = 1/60 → 13.3 px per step against a
// 12 px paddle. A naive "widen the band" fix bounces a ball that already
// missed the paddle; the second test refuses it.
const DT = 1 / 60;
const DT_MAX = 0.05;

function paddleCentered(state) {
  state.paddle.x = (WIDTH - PADDLE_W) / 2;
  return state;
}

function ballAtPaddleCenter(state, vy) {
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R, r: BALL_R, vx: 0, vy };
  return state;
}

test('D7: fast ball crosses the paddle face and must bounce at the top', () => {
  const state = ballAtPaddleCenter(paddleCentered(createState(7)), ballSpeed(7));

  const lost = step(state, DT);

  assert.equal(lost, false, 'fast ball must bounce off the paddle, not fall through');
  assert.ok(state.ball.vy < 0, `vy must flip up after the paddle bounce: ${state.ball.vy}`);
  assert.equal(
    state.ball.y + state.ball.r,
    PADDLE_Y,
    'after the bounce the ball rests exactly on the top face',
  );
});

test('D7: a ball below the paddle has missed it and must keep falling', () => {
  const state = paddleCentered(createState(1));
  state.ball = { x: WIDTH / 2, y: PADDLE_Y + PADDLE_H, r: BALL_R, vx: 0, vy: ballSpeed(1) };

  step(state, DT);

  assert.ok(state.ball.vy > 0, `a missed paddle must not bounce the ball up: ${state.ball.vy}`);
});

// D8 — a contact at the exact center of the paddle gives hit = 0 and vx = 0:
// the ball loops vertically. The exit angle is bounded away from vertical.
test('D8: center paddle hit must not send the ball vertical', () => {
  const state = ballAtPaddleCenter(paddleCentered(createState(1)), ballSpeed(1));

  step(state, DT);

  assert.ok(state.ball.vx !== 0, `vx must stay playable: ${state.ball.vx}`);
  assert.ok(
    Math.abs(state.ball.vx) >= ballSpeed(1) * 0.15,
    `vx must not be near zero: ${state.ball.vx}`,
  );
});

// D9 — the paddle bounce rewrites vx without renormalizing: at hit = 0.8 the
// speed becomes 288.4 instead of 260 (up to 1.166x on the edge).
test('D9: paddle bounce conserves the level speed', () => {
  const state = paddleCentered(createState(1));
  const hit = 0.8;
  state.ball = {
    x: WIDTH / 2 + hit * (PADDLE_W / 2),
    y: PADDLE_Y - BALL_R,
    r: BALL_R,
    vx: 0,
    vy: ballSpeed(1),
  };

  step(state, DT);

  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(
    Math.abs(norm - ballSpeed(1)) < 0.5,
    `speed must be conserved: |v| = ${norm}, speed = ${ballSpeed(1)}`,
  );
});

// D10 — the same trajectory must collide the same way at 60 fps and at the
// capped 50 ms frame: at level 6 the capped step (35.5 px) jumps over the
// brick (34 px) that the 60 fps step (11.8 px) still lands inside.
test('D10: same trajectory, same collision at 60 fps and at the dt cap', () => {
  const mk = () => {
    const state = createState(6);
    state.bricks = [{ x: 100, y: 100, w: 72, h: 20, row: 0, alive: true, points: 10 }];
    state.ball = { x: 136, y: 128, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
    return state;
  };

  const at60 = mk();
  step(at60, DT);
  const atCap = mk();
  step(atCap, DT_MAX);

  assert.equal(at60.bricks[0].alive, atCap.bricks[0].alive, 'brick fate must not depend on dt');
  assert.equal(Math.sign(at60.ball.vy), Math.sign(atCap.ball.vy), 'bounce must not depend on dt');
  assert.ok(at60.ball.vy > 0, `must bounce up at 60 fps: ${at60.ball.vy}`);
  assert.ok(atCap.ball.vy > 0, `must bounce up at the dt cap: ${atCap.ball.vy}`);
});

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

