// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — the face is chosen by the penetration comparison in
// resolveBricks() below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

function clamp(value, min, max) {
  return value < min ? min : value > max ? max : value;
}

// --- Brick collision resolution (pure logic) --------------------------------

// Resolves a discrete overlap between the ball and the live bricks: every
// overlapped brick is destroyed and scored, and the ball receives ONE bounce
// off the overlapping set — the axis of smallest penetration (both axes on a
// corner), with the ball pushed back out of the rectangle. Returns the number
// of bricks destroyed (0 if the ball overlaps nothing).
function resolveBricks(state) {
  const { ball } = state;
  const hit = state.bricks.filter((b) => b.alive && collides(ball, b));
  if (hit.length === 0) return 0;

  // Smallest penetration per axis across the whole set: on a grid seam the
  // ball overlaps two bricks at once (BRICK_GAP 8 < ball diameter 14), and the
  // set must resolve as a single bounce, or two `vy = -vy` cancel out and the
  // ball sails through the seam.
  let minX = Infinity;
  let minY = Infinity;
  let minXBrick = null;
  let minYBrick = null;
  for (const brick of hit) {
    const penX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
    const penY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
    if (penX < minX) {
      minX = penX;
      minXBrick = brick;
    }
    if (penY < minY) {
      minY = penY;
      minYBrick = brick;
    }
  }

  for (const brick of hit) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // One bounce per pass: the hit axis is the smaller penetration; equal
  // penetrations are a corner, where both axes flip. Push the ball back out
  // on the same axis so the next pass starts outside the rectangle.
  if (minX < minY) {
    ball.vx = -ball.vx;
    ball.x += ball.x < minXBrick.x + minXBrick.w / 2 ? -minX : minX;
  } else if (minY < minX) {
    ball.vy = -ball.vy;
    ball.y += ball.y < minYBrick.y + minYBrick.h / 2 ? -minY : minY;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x += ball.x < minXBrick.x + minXBrick.w / 2 ? -minX : minX;
    ball.y += ball.y < minYBrick.y + minYBrick.h / 2 ? -minY : minY;
  }
  return hit.length;
}

// Entry time (0..1) of the segment (px,py)->(px+dx,py+dy) into the brick's
// box inflated by the ball radius — a swept AABB test (slab method). Returns
// null if the segment never enters the box; otherwise the entry time and the
// entry time of each slab, used to decide which face was hit.
function sweptEntry(px, py, dx, dy, brick, r) {
  let tEnter = 0;
  let tExit = 1;
  let axisX = 0;
  let axisY = 0;

  if (Math.abs(dx) < 1e-12) {
    if (px < brick.x - r || px > brick.x + brick.w + r) return null;
  } else {
    let t1 = (brick.x - r - px) / dx;
    let t2 = (brick.x + brick.w + r - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    axisX = t1;
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
  }
  if (Math.abs(dy) < 1e-12) {
    if (py < brick.y - r || py > brick.y + brick.h + r) return null;
  } else {
    let t1 = (brick.y - r - py) / dy;
    let t2 = (brick.y + brick.h + r - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    axisY = t1;
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
  }
  if (tEnter > tExit || tEnter > 1) return null;
  return { t: Math.max(tEnter, 0), axisX, axisY };
}

// Swept (continuous) brick detection: the ball moved from (prevX, prevY) to
// its current position within one step, and even if neither endpoint overlaps
// a brick the segment may cross one (tunneling: at level 6 a capped 50 ms
// step is 35.5 px against the 34 px of brick + ball diameter). Destroys every
// brick entered at the earliest instant — a seam is one pass, not two — and
// applies ONE bounce at the entry point. Returns the number of bricks
// destroyed (0 if the path crosses nothing).
function resolveBricksSwept(state, prevX, prevY) {
  const { ball } = state;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let best = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const entry = sweptEntry(prevX, prevY, dx, dy, brick, ball.r);
    if (entry !== null && (best === null || entry.t < best.entry.t)) {
      best = { brick, entry };
    }
  }
  if (best === null) return 0;

  let broken = 0;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const entry = sweptEntry(prevX, prevY, dx, dy, brick, ball.r);
    if (entry !== null && entry.t <= best.entry.t + 1e-9) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      broken += 1;
    }
  }

  // Place the ball at the entry point and bounce off the face it entered:
  // the face is the slab whose boundary was crossed last.
  ball.x = prevX + dx * best.entry.t;
  ball.y = prevY + dy * best.entry.t;
  if (best.entry.axisY > best.entry.axisX) {
    ball.vy = -ball.vy;
  } else if (best.entry.axisX > best.entry.axisY) {
    ball.vx = -ball.vx;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
  return broken;
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

