// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. Brick collision is resolved here (a
// swept test along the step catches crossings that no endpoint overlaps) and
// again in frame() for the draw pass — idempotent, so at most one bounce per
// pass either way.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: a swept test on the top face. A fast ball (level 7 at 60 fps:
  // 13.3 px per step against a 12 px paddle) used to jump over the discrete
  // band check and fall through; the crossing of paddle.y during the step is
  // what matters, not the resting position after it. The exit direction is
  // bounded away from the vertical dead zone (a center hit used to give
  // vx = 0) and conserves the level speed exactly (the old rewrite grew the
  // norm to 1.166x on the edge).
  const prevBottom = prevY + ball.r;
  const newBottom = ball.y + ball.r;
  if (ball.vy > 0 && prevBottom <= paddle.y && newBottom >= paddle.y) {
    const t = (paddle.y - prevBottom) / (newBottom - prevBottom);
    const hitX = prevX + (ball.x - prevX) * t;
    if (hitX >= paddle.x && hitX <= paddle.x + paddle.w) {
      ball.y = paddle.y - ball.r;
      // The rebound angle depends on where the paddle was hit.
      const hit = clamp((hitX - (paddle.x + paddle.w / 2)) / (paddle.w / 2), -1, 1);
      let angle = hit * PADDLE_MAX_ANGLE;
      if (Math.abs(angle) < PADDLE_MIN_ANGLE) {
        angle = (hit < 0 ? -1 : 1) * PADDLE_MIN_ANGLE;
      }
      const speed = ballSpeed(state.level);
      ball.vx = speed * Math.sin(angle);
      ball.vy = -speed * Math.cos(angle);
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Bricks: discrete overlap at the resting position first, then a swept
  // test along the step for a crossing that ends nowhere overlapping.
  if (resolveBricks(state) === 0) {
    resolveBricksSwept(state, prevX, prevY);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;

